// i18n — Carino DICOM dashboard. Fleet convention (see Topo/js/i18n.js and the
// bundled editor/i18n.js): English source strings ARE the keys, so a missing
// entry falls back to English and nothing ever renders blank. carino-lang.js
// (deferred, loaded just before this script) resolves the locale and fires
// 'carino:langchange'; this file owns the dictionaries and re-applies.
//
// Markup:  data-i18n            → textContent
//          data-i18n-html       → innerHTML (leaves carrying <em>/<code>)
//          data-i18n-title      → title attribute
//          data-i18n-placeholder→ placeholder attribute
//          data-i18n-aria-label → aria-label attribute
// Dynamic: the dashboard (pacs/web/js/*.js) wraps its literals in T() / TF() / TN() → window.t / .tn.
//          Template rows are cloned outside the document, so the dashboard calls
//          window.applyI18nIn(clone) on each one.
//
// Deliberately NOT translated, because they are protocol identifiers a
// technologist matches character-for-character against the modality's config:
// DICOM, PACS, AE, SCP, SCU, MWL, RIS, HL7, MLLP, TLS, mTLS, SC, C-FIND,
// C-ECHO, ORM^O01, PDF, port numbers, AE titles. Log lines and API messages
// come from the Python engine and stay in the server's language.
// Such a string may carry NO entry in the blocks below — the English literal
// is the identifier, so the t() fallback renders it verbatim in every locale
// ('Print SCP', 'MWL SCP', 'mTLS' and '→ SC' were deliberately emptied out).
// An identity entry (value byte-identical to the key) is equivalent and also
// appears; both mean "leave it alone". Do not "fix" either by translating.
//
// Two documented exceptions, both deliberate:
//   ru writes RIS as 'РИС' throughout — it is a real Russian abbreviation and
//     is used consistently across every RIS string, not drift.
//   ru renders the 'Worklist' card/chip label as 'MWL' because the Russian
//     noun ('Рабочий список') busts the navbar chip budget; ja keeps
//     'ワークリスト', which fits. Width decides, per locale.

