        'Workstations search this PC and pull studies back.': 'Las estaciones buscan y recuperan estudios de este PC.',
        'A workstation searches this PC by C-FIND and pulls studies back with C-MOVE or C-GET, answered out of the instance index. Turn it on when other equipment must fetch studies from here instead of waiting to be sent them.': 'Una estación busca estudios en este PC con C-FIND y los recupera con C-MOVE o C-GET, respondiendo desde el índice. Actívalo cuando otros equipos deban venir a buscar los estudios en lugar de esperar a que se los envíen.',

        // ── Routing panel ──
        'rules · which node gets what': 'reglas · qué nodo recibe qué',
        'Route by rule — otherwise every study goes to every enabled destination': 'Enrutar por reglas — si no, cada estudio va a todos los destinos habilitados',
        'Rules are read top to bottom. A rule with no destination is a filter and falls through; a rule whose destinations are all missing or disabled falls through too. If nothing matches, the study goes to every enabled destination — a study is never sent nowhere. The one exception: while the de-identification profile is off, a destination a rule asks to de-identify for is held rather than sent identified.': 'Las reglas se leen de arriba abajo. Una regla sin destino es un filtro y deja pasar; una regla cuyos destinos falten o estén deshabilitados también deja pasar. Si no coincide ninguna, el estudio va a todos los destinos habilitados: nunca se queda sin enviar. La única excepción: mientras el perfil de anonimización esté desactivado, un destino para el que una regla pide anonimizar queda retenido en vez de recibir el estudio identificado.',
        '+ Add rule': '+ Añadir regla',
        'Save rules': 'Guardar reglas',
        'No rules yet — every study goes to every enabled destination.': 'Aún no hay reglas: cada estudio va a todos los destinos habilitados.',
        'Test a study': 'Probar un estudio',
        'the sending AE title': 'el AE que envía',
        'Station': 'Estación',
        'Station name': 'Nombre de estación',
        'Blank fields are treated as empty on the study, not as wildcards.': 'Los campos en blanco se tratan como vacíos en el estudio, no como comodines.',
        'Explain route': 'Explicar ruta',
        'Rule name': 'Nombre de la regla',
        'Move this rule earlier': 'Subir esta regla',
        'Move this rule later': 'Bajar esta regla',
        'Remove this rule': 'Eliminar esta regla',
        'any': 'cualquiera',
        'Send to': 'Enviar a',
        'De-identify': 'Anonimizar',
        'Stop at this rule': 'Parar en esta regla',
        'Unknown match field {keys} — the engine skips this rule entirely.': 'Campo de coincidencia desconocido {keys}: el motor se salta esta regla entera.',
        '{name} — not an enabled destination, so this rule cannot deliver to it': '{name}: no es un destino habilitado, así que esta regla no puede entregarle nada',
        '→ nowhere: there is no enabled destination at all.': '→ a ninguna parte: no hay ningún destino habilitado.',
        '→ nowhere: every destination is held.': '→ a ninguna parte: todos los destinos están retenidos.',
        'HELD — not sent to {dests}: a rule asks for de-identification and the profile is off, so nothing can be scrubbed.': 'RETENIDO — no se envía a {dests}: una regla pide anonimización y el perfil está desactivado, así que no se puede limpiar nada.',
        'HELD — not sent to {dests}: a rule asks for de-identification, the profile is on, and no de-identifier can be built from these settings, so nothing can be scrubbed.': 'RETENIDO — no se envía a {dests}: una regla pide anonimización, el perfil está activado y con estos ajustes no se puede construir ningún anonimizador, así que no se puede limpiar nada.',
        'HELD — not sent to {dests}: a rule asks for de-identification and nothing can be scrubbed.': 'RETENIDO — no se envía a {dests}: una regla pide anonimización y no se puede limpiar nada.',
