        '{n} of {m} — {names} stopped': '{n} de {m} — {names} detenido',
        'Off': 'Apagado',
        'Not armed': 'Sin armar',
        'Armed · watching {n}': 'Armada · vigila {n}',
        'last probe {ts}': 'última sonda {ts}',
        'Copied: {text}': 'Copiado: {text}',
