        'Copied the visible lines.': 'Líneas visibles copiadas.',
        'This browser would not copy (the clipboard needs https or localhost) — use Download instead.': 'Este navegador no quiso copiar (el portapapeles necesita https o localhost): usa Descargar.',
        'Row {n}: {field} is missing': 'Fila {n}: falta {field}',
        'Row {n}: {field} is not valid': 'Fila {n}: {field} no es válido',
        'Rule {n}: {value} is longer than 16 characters': 'Regla {n}: {value} tiene más de 16 caracteres',
        'Saved — {changes}': 'Guardado — {changes}',
        '{services} stopped': '{services}: detenido',
        '{services} started': '{services}: iniciado',
        '{services} restarted': '{services}: reiniciado',
        'Not saved — your profile is not allowed to make this change (it needs: {caps}).': 'No guardado: tu perfil no puede hacer este cambio (necesita: {caps}).',
        'Modalities sending to {aet} will get errors until it is started again.': 'Las modalidades que envían a {aet} recibirán errores hasta que se inicie de nuevo.',
        'Modalities printing to {aet} will get errors until it is started again.': 'Las modalidades que imprimen en {aet} recibirán errores hasta que se inicie de nuevo.',
        'Modalities asking {aet} for their worklist will get errors until it is started again.': 'Las modalidades que piden su worklist a {aet} recibirán errores hasta que se inicie de nuevo.',
