        "Tick a destination's 🚨 box (in <em>Destinations</em>) to mark it a primary. When it's unreachable past the threshold you get a pop-up to activate the emergency worklist; studies received meanwhile are held and back-filled when it returns.": 'Marque a caixa 🚨 de um destino (em <em>Destinos</em>) para defini-lo como primário. Quando ele ficar inacessível além do limite, aparece um aviso para ativar a worklist de emergência; os estudos recebidos nesse meio-tempo ficam retidos e são enviados quando ele voltar.',
