        'An order aimed at one of these appears on <em>that</em> station\'s worklist and no other. An order with no target appears on every one — which is what you want during an outage, and not what you want when you are testing a single room.': 'Um pedido dirigido a uma destas aparece na worklist <em>daquela</em> estação e de nenhuma outra. Um pedido sem destino aparece em todas — que é o que você quer numa queda, e não é o que você quer ao testar uma sala só.',
        'No modalities registered yet. Until one is, an order\'s target is typed in by hand and a typo cannot be caught.': 'Nenhuma modalidade cadastrada ainda. Até haver uma, o destino de um pedido é digitado à mão e um erro de digitação não tem como ser pego.',
