        '{n} incoming studies were REFUSED for low disk space and never arrived. Nothing retries them from this side — the sender has to send them again once there is space.': '{n} estudos recebidos foram RECUSADOS por falta de espaço em disco e nunca chegaram. Nada os reenvia deste lado — quem enviou precisa enviar de novo quando houver espaço.',
