        'Workstations search this PC and pull studies back.': 'As estações buscam e recuperam estudos deste PC.',
        'A workstation searches this PC by C-FIND and pulls studies back with C-MOVE or C-GET, answered out of the instance index. Turn it on when other equipment must fetch studies from here instead of waiting to be sent them.': 'Uma estação busca estudos neste PC com C-FIND e os recupera com C-MOVE ou C-GET, respondendo a partir do índice. Ligue quando outros equipamentos precisarem buscar os estudos aqui em vez de esperar que sejam enviados.',

        // ── Routing panel ──
        'rules · which node gets what': 'regras · qual nó recebe o quê',
        'Route by rule — otherwise every study goes to every enabled destination': 'Rotear por regras — caso contrário, cada estudo vai para todos os destinos ativos',
        'Rules are read top to bottom. A rule with no destination is a filter and falls through; a rule whose destinations are all missing or disabled falls through too. If nothing matches, the study goes to every enabled destination — a study is never sent nowhere. The one exception: while the de-identification profile is off, a destination a rule asks to de-identify for is held rather than sent identified.': 'As regras são lidas de cima para baixo. Uma regra sem destino é um filtro e deixa passar; uma regra cujos destinos sumiram ou estão desativados também deixa passar. Se nada corresponder, o estudo vai para todos os destinos ativos: nunca fica sem ser enviado. A única exceção: enquanto o perfil de anonimização estiver desligado, um destino para o qual uma regra pede anonimização fica retido em vez de receber o estudo identificado.',
        '+ Add rule': '+ Nova regra',
        'Save rules': 'Salvar regras',
        'No rules yet — every study goes to every enabled destination.': 'Ainda não há regras: cada estudo vai para todos os destinos ativos.',
