        'Send to': 'Enviar para',
        'De-identify': 'Anonimizar',
        'Stop at this rule': 'Parar nesta regra',
        'Unknown match field {keys} — the engine skips this rule entirely.': 'Campo de correspondência desconhecido {keys}: o motor pula esta regra inteira.',
        '{name} — not an enabled destination, so this rule cannot deliver to it': '{name}: não é um destino ativo, então esta regra não consegue entregar nada a ele',
        '→ nowhere: there is no enabled destination at all.': '→ para lugar nenhum: não há nenhum destino ativo.',
        '→ nowhere: every destination is held.': '→ para lugar nenhum: todos os destinos estão retidos.',
        'HELD — not sent to {dests}: a rule asks for de-identification and the profile is off, so nothing can be scrubbed.': 'RETIDO — não enviado para {dests}: uma regra pede anonimização e o perfil está desligado, então nada pode ser limpo.',
        'HELD — not sent to {dests}: a rule asks for de-identification, the profile is on, and no de-identifier can be built from these settings, so nothing can be scrubbed.': 'RETIDO — não enviado para {dests}: uma regra pede anonimização, o perfil está ligado e nenhum anonimizador pode ser construído com estas configurações, então nada pode ser limpo.',
        'HELD — not sent to {dests}: a rule asks for de-identification and nothing can be scrubbed.': 'RETIDO — não enviado para {dests}: uma regra pede anonimização e nada pode ser limpo.',
