        //    The confirmations are engine outcomes (server.py sends a code,
        //    the dashboard says the sentence): three of the four are the only place
        //    anybody is told the order is reaching no scanner, so they are
        //    translated rather than left as engine English.
        'Not stated — shows on every worklist': 'Não informado — aparece em todas as worklists',
        'A worklist matches this code exactly. Leave it blank and the order shows on every worklist.': 'A worklist compara este código de forma exata. Deixe em branco e o pedido aparece em todas as worklists.',
        'A worklist matches this AE title exactly. Leave it unset and the order shows on every worklist.': 'A worklist compara este AE de forma exata. Deixe sem definir e o pedido aparece em todas as worklists.',
        'Registered here — a console asks for these': 'Registradas aqui — algum equipamento as solicita',
        'Not registered here — no console asks for these': 'Não registradas aqui — nenhum equipamento as solicita',
        'Order queued, but no modality registered here answers to {code}, so a console that filters by modality will not see it. Pick the code the room is registered as, or hand the details to the tech.': 'Pedido enfileirado, mas nenhuma modalidade registrada aqui responde a {code}, então um equipamento que filtra por modalidade não o verá. Escolha o código com que a sala está registrada, ou passe os dados ao técnico.',
        'Dismiss this warning': 'Dispensar este aviso',
