        'Your profile may not do this — it needs the “{cap}” permission. Ask an administrator.': 'Seu perfil não pode fazer isto — precisa da permissão “{cap}”. Peça a um administrador.',
        'Your profile may not do this. Ask an administrator.': 'Seu perfil não pode fazer isto. Peça a um administrador.',
