        'Send {who} to its routed destinations?': 'Enviar {who} aos destinos do roteamento?',
        'Send {who} to: {dests}?': 'Enviar {who} para: {dests}?',
        'No enabled destination would receive {who} right now. Queue it anyway?': 'Nenhum destino ativo receberia {who} agora. Colocar na fila mesmo assim?',
        'Delete ALL {n} archived studies from disk? This cannot be undone.\n\nType {n} to confirm.': 'Excluir do disco TODOS os {n} estudos arquivados? Não dá para desfazer.\n\nDigite {n} para confirmar.',
        'Delete ALL {n} received studies from disk? This cannot be undone.\n\nType {n} to confirm.': 'Excluir do disco TODOS os {n} estudos recebidos? Não dá para desfazer.\n\nDigite {n} para confirmar.',
        'Nothing deleted — the number did not match.': 'Nada foi excluído — o número não confere.',
        'Copying {i}/{n}': 'Copiando {i}/{n}',
        'Add “{file}” to {who} as a new series?': 'Adicionar “{file}” a {who} como nova série?',
        'Clears itself when the node answers — Retry now only skips the wait.': 'Resolve-se sozinho quando o nó responder — Tentar agora só pula a espera.',
        'Routed to a name that is no longer an enabled destination — nothing retries these.': 'Roteados para um nome que não é mais um destino ativo — nada os reenvia.',
        'A rule asks for a de-identified copy that cannot be made — one edit releases them.': 'Uma regra pede uma cópia anonimizada que não pode ser feita — uma edição os libera.',
        'Only the files listed on this row are affected.': 'Só os arquivos listados nesta linha são afetados.',
