        'Cancel this order? It moves to Closed.': 'Cancelar este pedido? Ele vai para Fechados.',
        'Delete this order permanently? It is removed from the Closed list.': 'Excluir este pedido permanentemente? Ele sai da lista de Fechados.',
        'Delete this order permanently? It is removed from this list and from the worklist.': 'Excluir este pedido permanentemente? Ele sai desta lista e da worklist.',
        'Save changes': 'Salvar alterações',
