        'Give the modality: AE {aet} · IP {ip} · port {port}': 'Informe ao equipamento: AE {aet} · IP {ip} · porta {port}',
        'Enter or generate the new site key first.': 'Digite ou gere primeiro a nova chave do site.',
        'Type the current access token first — changing the site key needs it.': 'Digite primeiro o token de acesso atual — mudar a chave do site exige isso.',
        'Replace the site key? Everything exported from now on gets different pseudonyms and date shifts, so it will no longer line up with what was exported before.': 'Substituir a chave do site? Tudo o que for exportado a partir de agora terá outros pseudônimos e deslocamentos de data, e não vai bater com o que foi exportado antes.',
        'Remove the site key? Pseudonyms are then derived from the study alone, and anyone with this software can reverse them.': 'Remover a chave do site? Os pseudônimos passam a derivar só do estudo, e qualquer um com este software poderá revertê-los.',
