        'Modalities sending to {aet} will get errors until it is started again.': 'Os equipamentos que enviam para {aet} vão receber erros até que ele seja iniciado de novo.',
        'Modalities printing to {aet} will get errors until it is started again.': 'Os equipamentos que imprimem em {aet} vão receber erros até que ele seja iniciado de novo.',
