        'Point a print-only modality at this AE / port as its DICOM printer. Each captured film is queued in <em>📎 Pending</em> for you to identify, then Approve to convert to DICOM and forward.': '印刷しかできない装置のDICOMプリンタとして、このAE／ポートを指定してください。取り込んだフィルムは<em>📎 保留</em>に入るので患者情報を確認し、承認するとDICOMに変換して転送します。',
