        'Hold &amp; forward — queue received studies for the primary while active': '保留して転送 — 有効な間、受信した検査をプライマリ宛にためておく',
        "Tick a destination's 🚨 box (in <em>Destinations</em>) to mark it a primary. When it's unreachable past the threshold you get a pop-up to activate the emergency worklist; studies received meanwhile are held and back-filled when it returns.": '<em>送信先</em>で🚨のチェックを入れると、その送信先がプライマリになります。しきい値を超えて到達できない場合、緊急ワークリストを有効化するダイアログが表示されます。その間に受信した検査は保留され、復旧時にまとめて送信されます。',
        'Modality Worklist (MWL)': 'Modality Worklist（MWL）',
        'Worklist AE title': 'ワークリストの AE title',
        'Serve worklist over TLS': 'ワークリストをTLSで提供',
        "Point a modality at this AE / port as its <em>Modality Worklist</em> source. It pulls every <em>open</em> order (from 📋 Orders) by C-FIND; set an order's <em>Target modality AE</em> to steer it to one station. The order's Study UID is burned into the exam, so the returned study reconciles exactly.": '装置の<em>Modality Worklist</em>参照先としてこのAE／ポートを指定してください。C-FINDで（📋オーダの）<em>未処理</em>オーダをすべて取得します。オーダの<em>対象装置のAE</em>を設定すると、特定の装置だけに絞れます。オーダのStudy UIDが検査に焼き込まれるため、返ってきた検査は正確に突き合わせられます。',
        'Order store folder': 'オーダ保存フォルダ',
