        'Configuration': '設定一式',
        'The other RIS\'s worklist': '他のRISのワークリスト',
        'Where the hospital\'s own worklist lives. Only used by <em>Test worklist</em> on a modality — this appliance never queries it on a timer.': '病院側のワークリストの所在。モダリティの<em>ワークリスト確認</em>でのみ使用します。この装置が定期的に問い合わせることはありません。',
        'Host / IP': 'ホスト / IP',
