        'Connect over TLS': 'TLSで接続',
        'what another RIS answered': '他のRISの応答',
        'Take the modality off the network, then use <em>Test worklist</em> on its row under Configuration → Modalities. This asks the other RIS five questions using that modality\'s own AE title, relaxing one key at a time; the differences between the answers are what locate the fault.': 'モダリティをネットワークから外し、設定 → モダリティでその行の<em>ワークリスト確認</em>を使います。そのモダリティのAEタイトルで他のRISに5つの質問を、条件を1つずつ緩めながら行い、回答の違いが問題の所在を示します。',
