        'An order aimed at one of these appears on <em>that</em> station\'s worklist and no other. An order with no target appears on every one — which is what you want during an outage, and not what you want when you are testing a single room.': 'ここに登録した装置を指定したオーダーは<em>その</em>装置のワークリストにだけ表示されます。指定のないオーダーはすべての装置に表示されます。障害時にはそれが望ましく、1部屋だけを試験するときには望ましくありません。',
        'No modalities registered yet. Until one is, an order\'s target is typed in by hand and a typo cannot be caught.': 'モダリティはまだ登録されていません。登録するまで、オーダーの宛先は手入力となり、入力ミスを検出できません。',
