        'The RIS owns this order. It can be completed here when the study arrives, but only the RIS can cancel it.': 'このオーダーはRISのものです。検査が届けばここで完了しますが、取り消せるのはRISだけです。',
        'A test order behaves exactly like a real one — it reaches the worklist and matches a study back — but it is marked TEST everywhere and is not somebody\'s exam': 'テストオーダーは実際のオーダーと同じように動作し、ワークリストに出て戻ってきた検査と照合されますが、どこでも「テスト」と表示され、実際の検査ではありません',
