        '⚠ Low disk space — {free} free (below the {floor} GB floor). New incoming studies will be refused until space is freed.': '⚠ ディスク空き容量が不足しています — 残り{free}（下限{floor} GBを下回っています）。空き容量を確保するまで、新しい受信検査は拒否されます。',
