        '⚠ This configuration would be REFUSED if it were saved from this dashboard, and it is being used exactly as it stands: {problem} Fix it in Settings — no Save will go through until you do — or in the file at {path}.': '⚠ この設定はダッシュボードから保存しようとすると拒否されますが、そのまま使用されています: {problem} 「設定」で修正してください（修正するまで保存は通りません）。または {path} を直接編集してください。',

