        'Send {who} to: {dests}?': '{who} を次へ送信しますか：{dests}',
        'No enabled destination would receive {who} right now. Queue it anyway?': '現在 {who} を受け取る有効な送信先はありません。それでもキューに入れますか？',
        'Delete ALL {n} archived studies from disk? This cannot be undone.\n\nType {n} to confirm.': 'アーカイブした検査 {n} 件を「すべて」ディスクから削除しますか？元に戻せません。\n\n確認のため {n} と入力してください。',
        'Delete ALL {n} received studies from disk? This cannot be undone.\n\nType {n} to confirm.': '受信した検査 {n} 件を「すべて」ディスクから削除しますか？元に戻せません。\n\n確認のため {n} と入力してください。',
