        'Copying {i}/{n}': 'コピー中 {i}/{n}',
        'Add “{file}” to {who} as a new series?': '「{file}」を {who} に新しいシリーズとして追加しますか？',
        'Clears itself when the node answers — Retry now only skips the wait.': 'ノードが応答すれば自然に解消します。［今すぐ再試行］は待ち時間を飛ばすだけです。',
        'Routed to a name that is no longer an enabled destination — nothing retries these.': '有効な送信先でなくなった名前へルーティングされています。再試行されません。',
