        '{code} is not one of this site\'s modalities, so no order can be made for this room. Add it in Settings → Worklist and orders, or fix the code.': '{code} はこの施設のモダリティではないため、この検査室へのオーダーは作成できません。設定 → ワークリストとオーダー で追加するか、コードを修正してください。',
