        'Query and web access': '検索とWebアクセス',
        'Answers C-FIND, C-MOVE and C-GET out of the instance index, so keep the index on. A C-MOVE opens a NEW association to the receiving node and calls out with the Q/R AE title above, not the auto-send one — a node that filters on calling AE title must allow it, or every C-MOVE is rejected. C-MOVE destinations are resolved from qr.move_destinations in the config file.': 'C-FIND、C-MOVE、C-GETにインスタンス索引から応答するため、索引はオンのままにしてください。C-MOVEは受信ノードへ新しいアソシエーションを開き、自動送信ではなく上記のQ/R AEタイトルで接続します。呼び出し元AEタイトルで絞り込むノードでは、これを許可しないとすべてのC-MOVEが拒否されます。C-MOVEの送信先は設定ファイルの qr.move_destinations から解決されます。',
