        'Watch this node for emergency failover': 'Следить за этим узлом для аварийного переключения',
        'New files in the watched folder are forwarded to every <em>enabled</em> node, retried until each accepts. Tick <em>TLS</em> to connect to a node over DICOM-TLS — the client cert/CA come from the Auto-send settings.': 'Новые файлы в наблюдаемой папке пересылаются на каждый <em>включённый</em> узел с повторами, пока все не примут их. Отметьте <em>TLS</em>, чтобы подключаться к узлу по DICOM-TLS — клиентский сертификат и CA берутся из настроек Автоотправки.',
        '+ Add node': '+ Добавить узел',
