        '{name}: {host}:{port} is {what}, which does not store images. Studies sent there will fail — use the PACS\'s storage port (often 104 or 11112).': '{name}: {host}:{port} — это {what}, он не хранит изображения. Отправленные туда исследования не дойдут — укажите порт хранения PACS (обычно 104 или 11112).',
        'Remove': 'Удалить',
