        'Receiver (SCP)': 'Приём (SCP)',
        'Bind address': 'Адрес прослушивания',
        'Storage folder': 'Папка хранения',
        'Organize by Patient / Study / Series': 'Раскладывать по схеме Пациент / Исследование / Серия',
        'Refuse when free space below (GB)': 'Отказывать, если свободного места меньше (ГБ)',
