        '→ PDF': '→ PDF',
        'accession': '№ иссл.',
        '⚠ Low disk space — {free} free (below the {floor} GB floor). New incoming studies will be refused until space is freed.': '⚠ Мало места на диске — свободно {free} (ниже порога {floor} ГБ). Новые входящие исследования будут отклоняться, пока не освободится место.',
        '{n} incoming studies were REFUSED for low disk space and never arrived. Nothing retries them from this side — the sender has to send them again once there is space.': '{n} входящих исследований ОТКЛОНЕНЫ из-за нехватки места на диске и не были получены. С этой стороны их никто не повторит — отправителю нужно послать их снова, когда появится место.',
        '⚠ This configuration would be REFUSED if it were saved from this dashboard, and it is being used exactly as it stands: {problem} Fix it in Settings — no Save will go through until you do — or in the file at {path}.': '⚠ Эта конфигурация была бы ОТКЛОНЕНА при сохранении из панели, но используется как есть: {problem} Исправьте её в «Настройках» — ни одно сохранение не пройдёт, пока не исправите, — или в файле {path}.',

        "🚨 EMERGENCY ACTIVE — '{who}' unreachable. Worklist is serving; received studies are held for forward.": "🚨 АВАРИЙНЫЙ РЕЖИМ — «{who}» недоступен. Рабочий список обслуживается; принятые исследования удерживаются для пересылки.",
        "↩ '{who}' is back — flushing held studies to it. Click Resume when done.": '↩ «{who}» снова на связи — удержанные исследования отправляются ему. По завершении нажмите «Обычный режим».',
        "⚠ Primary '{who}' is unreachable — emergency RIS not activated.": '⚠ Основной узел «{who}» недоступен — аварийная РИС не включена.',
        'The primary PACS \'{who}\' has been unreachable past the failover threshold.': 'Основной PACS «{who}» недоступен дольше порога аварийного переключения.',
        'Resume normal': 'Обычный режим',
