        '{v} available': 'доступна {v}',
        'Check for new versions': 'Проверять новые версии',
        'Off unless you turn it on. Once a day this server asks GitHub for the number of the latest release, and Overview shows whether this one is current. Nothing about this machine, its studies or its users is sent, and nothing is downloaded.': 'Выключено, пока вы не включите. Раз в день этот сервер спрашивает у GitHub номер последнего выпуска, а Обзор показывает, актуальна ли эта версия. Ничего об этой машине, её исследованиях или пользователях не отправляется, и ничего не загружается.',
        'Check for updates': 'Проверить обновления',
        'Update ↗': 'Обновить ↗',
        'Opens the Carino DICOM website, where the new version can be downloaded': 'Открывает сайт Carino DICOM, где можно скачать новую версию',
        'could not check — GitHub is unreachable from this server': 'проверить не удалось — GitHub недоступен с этого сервера',
        'up to date': 'актуальна',
        'checking…': 'проверка…',
        'Check for new versions? Once a day this server asks GitHub for the number of the latest release. Nothing about this machine, its studies or its users is sent, and nothing is downloaded. You can turn it off in Settings → Integrations.': 'Проверять новые версии? Раз в день этот сервер спрашивает у GitHub номер последнего выпуска. Ничего об этой машине, её исследованиях или пользователях не отправляется, и ничего не загружается. Выключить можно в Настройки → Интеграции.',
