        // ── Query/Retrieve card + service name ──
        'Routing': 'Маршруты',
        'Query/Retrieve': 'Запрос/выдача',
        'Workstations search this PC and pull studies back.': 'Рабочие станции ищут и забирают исследования с этого ПК.',
        'A workstation searches this PC by C-FIND and pulls studies back with C-MOVE or C-GET, answered out of the instance index. Turn it on when other equipment must fetch studies from here instead of waiting to be sent them.': 'Рабочая станция ищет исследования на этом ПК по C-FIND и забирает их через C-MOVE или C-GET, ответы формируются из индекса. Включайте, когда другое оборудование должно само забирать исследования, а не ждать отправки.',

        // ── Routing panel ──
        'rules · which node gets what': 'правила · кому что уходит',
        'Route by rule — otherwise every study goes to every enabled destination': 'Маршрутизировать по правилам — иначе каждое исследование уходит на все включённые узлы',
        'Rules are read top to bottom. A rule with no destination is a filter and falls through; a rule whose destinations are all missing or disabled falls through too. If nothing matches, the study goes to every enabled destination — a study is never sent nowhere. The one exception: while the de-identification profile is off, a destination a rule asks to de-identify for is held rather than sent identified.': 'Правила читаются сверху вниз. Правило без узла назначения — это фильтр, оно пропускает дальше; правило, все узлы которого отсутствуют или выключены, тоже пропускает дальше. Если ничего не совпало, исследование уходит на все включённые узлы — оно никогда не остаётся неотправленным. Единственное исключение: пока профиль обезличивания выключен, узел, для которого правило требует обезличивания, удерживается, а не получает исследование с данными пациента.',
        '+ Add rule': '+ Правило',
        'Save rules': 'Сохранить',
        'No rules yet — every study goes to every enabled destination.': 'Правил пока нет — каждое исследование уходит на все включённые узлы.',
        'Test a study': 'Проверить исследование',
        'the sending AE title': 'AE-заголовок отправителя',
        'Station': 'Станция',
        'Station name': 'Имя станции',
        'Blank fields are treated as empty on the study, not as wildcards.': 'Пустые поля означают пустое значение в исследовании, а не «любое».',
        'Explain route': 'Проверить',
        'Rule name': 'Название правила',
        'Move this rule earlier': 'Поднять правило',
        'Move this rule later': 'Опустить правило',
        'Remove this rule': 'Удалить правило',
        'any': 'любое',
        'Send to': 'Отправлять на',
        'De-identify': 'Обезличить',
        'Stop at this rule': 'Остановиться здесь',
        'Unknown match field {keys} — the engine skips this rule entirely.': 'Неизвестное поле сопоставления {keys} — движок полностью пропускает это правило.',
        '{name} — not an enabled destination, so this rule cannot deliver to it': '{name} — не является включённым узлом, поэтому это правило туда ничего не доставит',
        '→ nowhere: there is no enabled destination at all.': '→ никуда: нет ни одного включённого узла.',
        '→ nowhere: every destination is held.': '→ никуда: все узлы удержаны.',
        'HELD — not sent to {dests}: a rule asks for de-identification and the profile is off, so nothing can be scrubbed.': 'УДЕРЖАНО — не отправлено на {dests}: правило требует обезличивания, а профиль выключен, поэтому очистить ничего нельзя.',
        'HELD — not sent to {dests}: a rule asks for de-identification, the profile is on, and no de-identifier can be built from these settings, so nothing can be scrubbed.': 'УДЕРЖАНО — не отправлено на {dests}: правило требует обезличивания, профиль включён, но с текущими настройками деидентификатор не создать, поэтому очистить ничего нельзя.',
        'HELD — not sent to {dests}: a rule asks for de-identification and nothing can be scrubbed.': 'УДЕРЖАНО — не отправлено на {dests}: правило требует обезличивания, а очистить ничего нельзя.',
        'HELD, not sent to {dests}': 'УДЕРЖАНО, не отправлено на {dests}',
        'De-identified for: {dests}': 'Обезличено для: {dests}',
        'Names a destination that does not exist or is disabled: {what}': 'Указан узел, которого нет или он выключен: {what}',
        'Routing is off — every study goes to every enabled destination.': 'Маршрутизация выключена — каждое исследование уходит на все включённые узлы.',
        'No rules were evaluated.': 'Правила не оценивались.',
