        'No C-MOVE destinations configured — a C-MOVE naming an unknown AE title is refused.': 'Узлы C-MOVE не заданы — C-MOVE с неизвестным AE title будет отклонён.',

        // ── DICOMweb ──
        'Serve DICOMweb (QIDO-RS / WADO-RS / STOW-RS)': 'Обслуживать DICOMweb (QIDO-RS / WADO-RS / STOW-RS)',
