        'https://viewer.example.org, blank = same-origin only': 'https://viewer.example.org, пусто = только тот же источник',
        'Base URL for a viewer': 'Базовый URL для просмотрщика',
        'Paste the base URL into a web viewer as its DICOMweb root. It answers out of the instance index, so keep the index on. Every request needs the API token when one is set; a browser viewer on another origin also has to be listed above.': 'Вставьте базовый URL в веб-просмотрщик как корень DICOMweb. Ответы идут из индекса объектов, поэтому индекс держите включённым. Если задан токен, он нужен каждому запросу; браузерный просмотрщик с другого источника должен быть ещё и в списке выше.',
        'DICOMweb is off — a viewer pointed at that URL gets 503.': 'DICOMweb выключен — просмотрщик по этому URL получит 503.',
        'On · {q} queries · {r} retrieved · {s} stored': 'Вкл. · запросов: {q} · выдано: {r} · сохранено: {s}',
        'read-only (STOW off)': 'только чтение (STOW выкл.)',

