        'Last write': 'Последняя запись',
        'Database': 'База данных',
        '↻ Rescan now': '↻ Скан заново',
        "Query/Retrieve and DICOMweb answer from this index, never by walking the disk. Rescan after copying studies into the storage folder behind the app's back — the walk runs in the background and reports in the Activity log.": 'Запрос/выдача и DICOMweb отвечают из этого индекса, а не обходом диска. Пересканируйте после того, как скопировали исследования в папку хранения в обход приложения — обход идёт в фоне и отчитывается в журнале.',
        'Index off — Query/Retrieve and DICOMweb have nothing to answer from.': 'Индекс выключен — Запросу/выдаче и DICOMweb нечем отвечать.',
        'Rescanning the storage folders…': 'Пересканирование папок хранения…',
        'The index was rebuilt empty after a version change and nothing has been scanned into it since — press Rescan now, or Query/Retrieve and DICOMweb keep answering as though this PACS held nothing.': 'После смены версии индекс был пересоздан пустым, и с тех пор в него ничего не сканировалось. Нажмите «Пересканировать», иначе Query/Retrieve и DICOMweb будут отвечать так, будто в этом PACS ничего нет.',
        'Rescanning…': 'Пересканирование…',
