        'More actions for {who}': 'Другие действия: {who}',
        'Path of this study on the server:': 'Путь к исследованию на сервере:',
        'Copied: {path}': 'Скопировано: {path}',
        '(held, not sent: {names})': '(удержано, не отправляется: {names})',
        'Send {who} to its routed destinations?': 'Отправить {who} по маршрутам?',
        'Send {who} to: {dests}?': 'Отправить {who} в: {dests}?',
        'No enabled destination would receive {who} right now. Queue it anyway?': 'Сейчас ни одно включённое назначение не примет {who}. Всё равно поставить в очередь?',
        'Delete ALL {n} archived studies from disk? This cannot be undone.\n\nType {n} to confirm.': 'Удалить с диска ВСЕ архивные исследования ({n})? Это необратимо.\n\nВведите {n} для подтверждения.',
        'Delete ALL {n} received studies from disk? This cannot be undone.\n\nType {n} to confirm.': 'Удалить с диска ВСЕ полученные исследования ({n})? Это необратимо.\n\nВведите {n} для подтверждения.',
        'Nothing deleted — the number did not match.': 'Ничего не удалено — число не совпало.',
        'Copying {i}/{n}': 'Копирование {i}/{n}',
        'Add “{file}” to {who} as a new series?': 'Добавить «{file}» к {who} новой серией?',
        'Clears itself when the node answers — Retry now only skips the wait.': 'Пройдёт само, когда узел ответит; «Повторить сейчас» лишь пропускает ожидание.',
        'Routed to a name that is no longer an enabled destination — nothing retries these.': 'Направлены на имя, которое больше не является включённым назначением, — повторов не будет.',
        'A rule asks for a de-identified copy that cannot be made — one edit releases them.': 'Правило требует обезличенную копию, которую нельзя сделать, — одна правка их освободит.',
        'Only the files listed on this row are affected.': 'Затрагиваются только файлы, перечисленные в этой строке.',
        'No other enabled destination to send to.': 'Нет другого включённого назначения для отправки.',
        'Image': 'Изображение',
        'hidden for your profile': 'скрыто для вашего профиля',
        'Hidden for your profile — kept exactly as it is': 'Скрыто для вашего профиля — сохраняется без изменений',
        'Choose an open order…': 'Выберите открытую заявку…',
        'No open orders': 'Нет открытых заявок',
        'Matched to order {who}': 'Связано с заявкой {who}',
        'Patient name and ID are needed — or match an order': 'Нужны имя и ID пациента — или свяжите с заявкой',
        'Send as {who} to: {dests}?': 'Отправить как {who} в: {dests}?',
        'Send as {who} to its routed destinations?': 'Отправить как {who} по маршрутам?',
        'DOB {d}': 'Д.р. {d}',
        'Sex {s}': 'Пол {s}',
        'Cancel this order? It moves to Closed.': 'Отменить заявку? Она перейдёт в Закрытые.',
        'Delete this order permanently? It is removed from the Closed list.': 'Удалить заявку навсегда? Она исчезнет из списка Закрытых.',
        'Delete this order permanently? It is removed from this list and from the worklist.': 'Удалить заявку навсегда? Она исчезнет из этого списка и из рабочего списка.',
        'Save changes': 'Сохранить',
        'Editing the order for {who}': 'Правка заявки: {who}',
        'Order updated': 'Заявка обновлена',
        'Add “{file}” to the order for {who}? It is sent as a new study and the order is closed.': 'Добавить «{file}» к заявке {who}? Файл уйдёт новым исследованием, а заявка закроется.',
        'Delete ALL closed orders?\n\nThis permanently empties the Closed list.': 'Удалить ВСЕ закрытые заявки?\n\nСписок Закрытых будет очищен навсегда.',

        // ── Studies / Orders review: filters, row menus, order match, confirmations ──
        'A field hidden from your profile is empty — ask someone who can see it to approve this file, or match an order.': 'Скрытое для вашего профиля поле пустое — попросите того, кто его видит, утвердить файл, или сопоставьте с заявкой.',

        // ── Services cards, Settings groups, Logs/Audit tools (UI review) ──
        'Failover': 'Резервирование',
        'Connect your equipment': 'Подключите оборудование',
        'Point the modality at': 'Направьте модальность на',
        'Point the RIS at': 'Направьте РИС на',
        'Point the workstation at': 'Направьте рабочую станцию на',
        'Copy': 'Копировать',
        'Copy the address': 'Скопировать адрес',
        'See the log': 'Открыть журнал',
        'Test': 'Проверить',
        'Connect to this service from this PC and report whether it answers': 'Подключиться к этой службе с этого ПК и сообщить, отвечает ли она',
        '⚙ Settings': '⚙ Настройки',
        'Captured': 'Захвачено',
        'Send a test print': 'Отправить тестовую печать',
        'Print one grayscale test sheet to this receiver from this PC; it lands in Pending': 'Напечатать с этого ПК один серый тестовый лист на этот приёмник; он попадёт в «Ожидающие»',
        'Someone else changed the configuration after you opened it, so your changes were not saved. Reload to see theirs, then make your edit again.': 'Кто-то изменил конфигурацию после того, как вы её открыли, поэтому ваши изменения не сохранены. Перезагрузите, чтобы увидеть их правку, и повторите свою.',
        'Reload': 'Перезагрузить',
        'Read-only: your profile can see the routing but not change it.': 'Только чтение: ваш профиль видит маршрутизацию, но не может её менять.',
        '<em>No RIS</em> — that PACS has no RIS of its own, so this PC runs the worklist for it permanently. <em>Failover</em> — watch that node and offer the emergency worklist if it goes offline.': '<em>Без РИС</em> — у этого PACS нет своего РИС, поэтому этот ПК постоянно ведёт для него рабочий список. <em>Резервирование</em> — следить за узлом и предложить аварийный рабочий список, если он недоступен.',
        'Fill in what the study would carry and see which rule wins, and why. Nothing is sent and nothing is written to the log. The rules as they are on screen are tested, saved or not.': 'Укажите, что нёс бы файл, и посмотрите, какое правило победит и почему. Ничего не отправляется и не пишется в журнал. Проверяются правила в том виде, как они на экране, сохранены они или нет.',
        'This PACS': 'Этот PACS',
