        'Worklist and orders': 'Рабочий список и заказы',
        'Which modalities does this site have?': 'Какие модальности есть в этом учреждении?',
        'Orders can only be made for these, and the rooms you register are checked against them. Leave everything unticked to allow all of them.': 'Заказы можно будет создавать только для них, а регистрируемые кабинеты сверяются с этим списком. Ничего не отмечайте, чтобы разрешить все.',
        'Modalities at this site': 'Модальности этого учреждения',
        'The order form offers only these, and a registered room with any other code is flagged. Orders from the hospital RIS for another modality are still accepted, with a warning in the log. Nothing ticked means every modality is allowed.': 'Форма заказа предлагает только их, а кабинет, зарегистрированный с другим кодом, помечается. Заказы из RIS больницы для другой модальности по-прежнему принимаются, с предупреждением в журнале. Если ничего не отмечено, разрешены все модальности.',
        '{code} is not one of this site\'s modalities, so no order can be made for this room. Add it in Settings → Worklist and orders, or fix the code.': '{code} не входит в модальности этого учреждения, поэтому заказ для этого кабинета создать нельзя. Добавьте её в Настройки → Рабочий список и заказы или исправьте код.',
        'Show all codes': 'Показать все коды',
        'Printing': 'Печать',
        'PDF keeps each sheet exactly as printed, but many viewers and PACS do not display Encapsulated PDF — choose Image if yours does not.': 'PDF сохраняет каждый лист точно как напечатан, но многие просмотрщики и PACS не показывают Encapsulated PDF — выберите «Изображение», если ваш не показывает.',
        'Accept colour jobs (colour-only modalities can\'t print if off)': 'Принимать цветные задания (если выключено, только цветные модальности не смогут печатать)',
        'Query and web access': 'Запросы и веб-доступ',
        'Answers C-FIND, C-MOVE and C-GET out of the instance index, so keep the index on. A C-MOVE opens a NEW association to the receiving node and calls out with the Q/R AE title above, not the auto-send one — a node that filters on calling AE title must allow it, or every C-MOVE is rejected. C-MOVE destinations are resolved from qr.move_destinations in the config file.': 'Отвечает на C-FIND, C-MOVE и C-GET из индекса объектов, поэтому индекс держите включённым. C-MOVE открывает НОВУЮ ассоциацию к принимающему узлу и представляется указанным выше AE title Q/R, а не AE автоотправки: узел, фильтрующий по вызывающему AE title, должен его разрешить, иначе каждый C-MOVE будет отклонён. Узлы C-MOVE берутся из qr.move_destinations в файле конфигурации.',
        'Privacy and security': 'Конфиденциальность и безопасность',
